import{_ as t,o as a,c as o,l as d}from"./chunks/framework.-NaojeWQ.js";const h=JSON.parse('{"title":"A reference you can hand to an agent.","description":"","frontmatter":{},"headers":[],"relativePath":"agents.md","filePath":"agents.md"}'),n={name:"agents.md"};function r(i,e,l,c,s,u){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="a-reference-you-can-hand-to-an-agent" tabindex="-1">A reference you can hand to an agent. <a class="header-anchor" href="#a-reference-you-can-hand-to-an-agent" aria-label="Permalink to &quot;A reference you can hand to an agent.&quot;">​</a></h1><p><a href="/de-gualle/llms-full.txt">Copy or download the complete plain-text guide</a>. <a href="/de-gualle/llms.txt">Entry-point index</a>.</p><h2 id="working-rules" tabindex="-1">Working rules <a class="header-anchor" href="#working-rules" aria-label="Permalink to &quot;Working rules&quot;">​</a></h2><ol><li>Use semantic HTML. Atoms are native elements, molecules have one coherent job, organisms compose them.</li><li>Do not invent classes. Use documented component/variant attributes only when native structure is insufficient.</li><li>Global CSS styles the document. Scoped imports require <code>data-de-gualle</code> on a containing element or the element itself.</li><li>For scoped whole-page styling, use <code>&lt;body data-de-gualle data-size=&quot;natural&quot;&gt;</code>.</li><li>Use native state attributes before ARIA. ARIA communicates state; it does not implement behaviour.</li><li>Ready is the normal enabled state. Loading is <code>aria-busy</code>; unavailability is normally <code>disabled</code>; read-only is <code>readonly</code>; explicit validation is <code>aria-invalid</code> plus an explanation.</li><li>Do not mark untouched required fields erroneous. A service failure is not an invalid input.</li><li>Keep labels, descriptions, keyboard focus and minimum control dimensions. Errors need text, not colour alone.</li><li>Include organism dependencies through package exports. Do not manually reconstruct dependency ordering.</li><li>Generate a theme from a seed colour; copy both mode palettes. Changing <code>--dg-brand</code> alone does not regenerate exported shades.</li><li>Sizing modes are <code>sm</code>, <code>md</code>, <code>lg</code>, and default <code>natural</code>, set on a styling boundary.</li><li>Optional behaviour belongs to the app or recipe. Do not assume CSS sends requests, cancels work, filters tables or manages custom keyboard patterns.</li><li>Preserve iOS 15/Safari 15.4 compatibility. Document any new CSS feature and its fallback in the feature ledger.</li><li>Use <code>ni</code>, <code>nr</code>, and <code>nlx</code> for package-manager commands in this project.</li></ol><h2 id="attribute-vocabulary" tabindex="-1">Attribute vocabulary <a class="header-anchor" href="#attribute-vocabulary" aria-label="Permalink to &quot;Attribute vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Attribute</th><th>Values / use</th></tr></thead><tbody><tr><td><code>data-de-gualle</code></td><td>Presence opts into scoped CSS</td></tr><tr><td><code>data-theme</code></td><td><code>light</code>, <code>dark</code>; omit for system</td></tr><tr><td><code>data-size</code></td><td><code>sm</code>, <code>md</code>, <code>lg</code>, <code>natural</code>; on boundary</td></tr><tr><td><code>data-variant</code></td><td>Button <code>secondary</code> or <code>danger</code>; anchor <code>primary</code> or <code>secondary</code>; buttons default to primary</td></tr><tr><td><code>data-grid</code></td><td>Responsive composition</td></tr><tr><td><code>data-stack</code></td><td>Vertical spacing</td></tr><tr><td><code>data-actions</code></td><td>Wrapping action row</td></tr><tr><td><code>data-overflow</code></td><td>Local horizontal scrolling</td></tr><tr><td><code>data-field</code></td><td>Label/control/help composition</td></tr><tr><td><code>data-chat</code></td><td>On named chat section</td></tr><tr><td><code>data-speaker</code></td><td>Message <code>user</code> or <code>assistant</code></td></tr><tr><td><code>data-composer</code></td><td>On message form</td></tr><tr><td><code>data-dashboard</code></td><td>On named dashboard section</td></tr><tr><td><code>data-tooltip</code></td><td>Optional nonessential decoration; not a full accessible tooltip</td></tr></tbody></table><p>Documentation-only <code>data-doc-*</code>, <code>data-intro</code>, preview and swatch attributes are not component exports. Prefer the canonical recipes linked below.</p><h2 id="canonical-recipes" tabindex="-1">Canonical recipes <a class="header-anchor" href="#canonical-recipes" aria-label="Permalink to &quot;Canonical recipes&quot;">​</a></h2><ul><li><a href="/de-gualle/elements.html">Forms and elements</a></li><li><a href="/de-gualle/states.html">State semantics</a></li><li><a href="/de-gualle/chat.html">Chat</a></li><li><a href="/de-gualle/dashboard.html">Dashboard</a></li><li><a href="/de-gualle/themes.html">Theme generation</a></li><li><a href="/de-gualle/compatibility.html">Compatibility constraints</a></li></ul>',9)])])}const p=t(n,[["render",r]]);export{h as __pageData,p as default};
